import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Exact-one unrestricted deck selection is private and keeps the existing shuffle/top continuation. */
public final class PrivateDeckTopSearchTest {
    static final UUID A=ResumableAbilityTest.A,B=ResumableAbilityTest.B,WATCH=ResumableAbilityTest.WATCH;
    static final String SEARCH="{\"type\":\"search_deck\",\"target\":\"DECK\",\"amount\":1,\"minimum\":1,\"destination\":\"DECK_TOP_AFTER_SHUFFLE\",\"reveal\":false}";
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
    static void reject(Runnable r){ResumableAbilityTest.rejects(r);}
    static EffectDefinition parse(String text){return EffectRegistry.standard().parse(JsonParser.parseString(text).getAsJsonObject());}
    static List<CardInstance> zone(ServerMatch m,String name){return GeneratedRuleBatch49Test.zone(m,A,name);}
    static void size(ServerMatch m,int n){var deck=zone(m,"deck");var removed=new ArrayList<>(deck.subList(0,Math.max(0,deck.size()-n)));deck.removeAll(removed);zone(m,"discard").addAll(removed);}
    static ServerMatch fixture(String effects){
        var ability=ResumableAbilityTest.ability("private-top",effects);
        var defs=List.of(new CardDefinition("basic","Basic fixture",CardCategory.POKEMON,TrainerCategory.NONE,"J",Set.of("international"),true,false,60,Map.of(),EffectSupport.SUPPORTED,null),new CardDefinition("secret-energy","Private energy",CardCategory.ENERGY,TrainerCategory.NONE,"J",Set.of("international"),false,true,60,Map.of(),EffectSupport.SUPPORTED,null),new CardDefinition("secret-trainer","Private trainer",CardCategory.TRAINER,TrainerCategory.ITEM,"J",Set.of("international"),false,false,60,Map.of(),EffectSupport.SUPPORTED,null));
        var combat=new CombatCatalog(Map.of("basic",new PokemonProfile(300,0,null,null,0,null,0,1,List.of(),List.of(ability))),Map.of("secret-energy",EnergyType.COLORLESS),Map.of("secret-trainer",new TrainerProfile(TrainerCategory.ITEM,new TrainerEffect(TrainerEffect.Opcode.DRAW,1,0))));
        var decks=new ArrayList<List<CardInstance>>();for(UUID owner:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(owner.getLeastSignificantBits(),i+1),owner,owner.equals(B)||i<40?"basic":i<50?"secret-energy":"secret-trainer"));decks.add(cards);}
        var m=new ServerMatch(A,B,decks.getFirst(),decks.getLast(),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(92));OpeningTestSupport.complete(m,A,B,1);if(m.currentPlayer().equals(B))m.endTurn(B);return m;
    }
    static void use(ServerMatch m){m.useAbility(A,m.activePokemonView(A).pokemonId(),"private-top");}
    static void pick(ServerMatch m,CardInstance card){var p=m.effectCardPrompt(A);m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(card.instanceId()));}
    public static void main(String[] args){schema();privateSelection();emptyAndSingleton();staleAndContinuation();prefixDepletion();concession();System.out.println("PrivateDeckTopSearchTest passed: strict private contract, exact-one any-category candidates, privacy/authority, empty/singleton, remainder-only shuffle, stale retry, prefix depletion and continuation");}
    static void schema(){
        var valid=parse(SEARCH);var op=ZoneSelectionEffect.forProgram(valid);check(op.toShuffledDeckTop()&&!op.revealsCards()&&op.selection().minimum()==1&&op.selection().maximum()==1,"private contract lost");
        for(String key:List.of("amount","minimum","destination","reveal")){var bad=JsonParser.parseString(SEARCH).getAsJsonObject();bad.remove(key);if(key.equals("destination"))continue;reject(()->ZoneSelectionEffect.forProgram(EffectRegistry.standard().parse(bad)));}
        for(String replacement:List.of(SEARCH.replace("\"minimum\":1","\"minimum\":0"),SEARCH.replace("\"amount\":1","\"amount\":2"),SEARCH.replace("\"DECK\"","\"HAND\""),SEARCH.replace("false","\"FALSE\"")))reject(()->ZoneSelectionEffect.forProgram(parse(replacement)));
        for(String extra:List.of("\"card_category\":\"POKEMON\"","\"definition_ids\":[\"basic\"]","\"basic_pokemon_only\":false","\"basic_energy_only\":false","\"top_count\":1","\"card_kinds\":[\"POKEMON\"]","\"label\":\"ignored\"","\"bind\":\"n\"","\"source_owner\":\"SELF\"","\"as_cost\":true","\"pokemon_names\":[\"Basic fixture\"]","\"excluded_definition_ids\":[\"basic\"]"))reject(()->ZoneSelectionEffect.forProgram(parse(SEARCH.substring(0,SEARCH.length()-1)+","+extra+"}")));
        var publicSearch=parse("{\"type\":\"search_deck\",\"target\":\"DECK\",\"amount\":1,\"minimum\":0,\"card_category\":\"TRAINER\",\"trainer_category\":\"SUPPORTER\",\"destination\":\"DECK_TOP_AFTER_SHUFFLE\",\"reveal\":true}");check(ZoneSelectionEffect.forProgram(publicSearch).revealsCards(),"old public mode rejected");
        var m=fixture(SEARCH);var before=m.clientView(A);reject(()->m.openEffectZoneSelection(A,valid,0));reject(()->m.openEffectDeckSearch(A,valid,0));check(before.equals(m.clientView(A)),"standalone private search mutated");
    }
    static void privateSelection(){
        var m=fixture(SEARCH);var s=MatchSession.multiplayer(m,A,B);s.addSpectator(WATCH);var deck=List.copyOf(zone(m,"deck"));var hand=List.copyOf(zone(m,"hand"));int rng=m.randomTranscript().size();int replay=m.replayTranscript().size();use(m);var p=m.effectCardPrompt(A);
        check(p.minimum()==1&&p.maximum()==1&&new HashSet<>(p.candidates()).equals(new HashSet<>(deck)),"private selection filters any category or is optional");
        check(!p.labelZh().contains("展示")&&!p.labelZh().contains("可以不选")&&p.labelZh().contains("1 张"),"private prompt falsely claims reveal or optional choice");
        check(p.candidates().stream().map(c->m.cardDefinition(c.definitionId()).category()).collect(java.util.stream.Collectors.toSet()).equals(Set.of(CardCategory.POKEMON,CardCategory.ENERGY,CardCategory.TRAINER)),"fixture lacks any-category proof");
        check(p.candidates().equals(p.candidates().stream().sorted(Comparator.comparing(CardInstance::definitionId).thenComparing(c->c.instanceId().toString())).toList()),"candidate prompt exposed current deck order");
        var selected=p.candidates().stream().filter(c->c.definitionId().equals("secret-trainer")).findFirst().orElseThrow();
        for(UUID viewer:List.of(B,WATCH)){var v=s.view(viewer,viewer.equals(B)?B:null);String json=new Gson().toJson(v);check(v.game().effectSelection()==null&&m.effectCardReveal()==null,"private choice exposed a prompt/reveal");for(var card:p.candidates())check(!json.contains(card.instanceId().toString()),"hidden physical identity leaked");check(!json.contains("secret-trainer"),"chosen/private face leaked");reject(()->m.submitEffectCards(viewer,p.resolutionId(),p.step(),List.of(selected.instanceId())));}
        for(int i=0;i<3;i++)check(s.view(A,A).game().effectSelection().equals(p),"refresh replaced private cursor");check(m.randomTranscript().size()==rng,"refresh consumed RNG");
        var snapshot=m.clientView(A);for(var ids:List.of(List.<UUID>of(),List.of(selected.instanceId(),selected.instanceId()),List.of(p.candidates().getFirst().instanceId(),p.candidates().getLast().instanceId()),List.of(m.privateView(B).hand().getFirst().instanceId())))reject(()->m.submitEffectCards(A,p.resolutionId(),p.step(),ids));
        reject(()->m.openEffectZoneSelection(A,parse(SEARCH),p.step()));check(snapshot.equals(m.clientView(A))&&m.randomTranscript().size()==rng,"invalid selection mutated/RNG");
        pick(m,selected);check(m.effectCardReveal()==null&&!m.hasPendingEffectChoice()&&zone(m,"hand").equals(hand),"private top placement exposed reveal/moved to hand/stalled");
        check(zone(m,"deck").size()==deck.size()&&new HashSet<>(zone(m,"deck")).equals(new HashSet<>(deck))&&zone(m,"deck").getLast().equals(selected),"selected card lost/shuffled/wrong top");
        var events=m.randomTranscript().subList(rng,m.randomTranscript().size());check(events.size()==Math.max(0,deck.size()-2),"did not shuffle remainder exactly once");for(int i=0;i<events.size();i++)check(events.get(i).bound()==deck.size()-1-i&&events.get(i).operation().equals("effect-search-to-top:"+A),"shuffle included selected card or changed operation");
        for(var event:m.replayTranscript().subList(replay,m.replayTranscript().size())){check(!event.operation().contains("展示")&&!event.operation().contains("可以不选"),"private replay/prompt falsely claims reveal/optional");for(var card:p.candidates())check(!event.operation().contains(card.instanceId().toString())&&!event.operation().contains(card.definitionId()),"private replay reveals chosen identity");}
        for(UUID viewer:List.of(B,WATCH)){String json=new Gson().toJson(s.view(viewer,viewer.equals(B)?B:null));check(!json.contains(selected.instanceId().toString())&&!json.contains("secret-trainer"),"resolved private card leaked");}
        check(!m.canUseAbility(A,m.activePokemonView(A).pokemonId(),"private-top"),"private search failed to reserve use");m.drawCardsByEffect(A,A,1);check(zone(m,"hand").contains(selected),"selected card was not next drawn");
    }
    static void emptyAndSingleton(){for(int n:List.of(0,1)){var m=fixture(SEARCH);size(m,n);int rng=m.randomTranscript().size();var before=m.clientView(A);if(n==0){check(!m.canUseAbility(A,m.activePokemonView(A).pokemonId(),"private-top"),"empty-only Ability allowed");reject(()->use(m));check(before.equals(m.clientView(A))&&m.abilityOptions(A).stream().noneMatch(ServerMatch.AbilityOption::usedThisTurn),"empty Ability changed state/usage");}else{var card=zone(m,"deck").getFirst();use(m);check(m.effectCardPrompt(A).minimum()==1,"singleton allowed failure to find");pick(m,card);check(zone(m,"deck").equals(List.of(card))&&m.effectCardReveal()==null,"singleton not retained privately");}check(m.randomTranscript().size()==rng,"empty remainder consumed RNG");}}
    static void staleAndContinuation(){var m=fixture(SEARCH+","+SEARCH+",{\"type\":\"draw\",\"amount\":1}");use(m);var first=m.effectCardPrompt(A);var card=first.candidates().getFirst();zone(m,"deck").remove(card);zone(m,"hand").add(card);var before=m.clientView(A);var rng=m.randomTranscript();reject(()->pick(m,card));check(before.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"stale zone partial commit");zone(m,"hand").remove(card);zone(m,"deck").add(card);pick(m,card);var second=m.effectCardPrompt(A);check(second.step()!=first.step()&&m.effectCardReveal()==null,"private suffix cursor lost");var now=m.clientView(A);reject(()->m.submitEffectCards(A,first.resolutionId(),first.step(),List.of(card.instanceId())));check(now.equals(m.clientView(A)),"old private choice replayed");var next=second.candidates().getLast();pick(m,next);check(zone(m,"hand").contains(next)&&!m.hasPendingEffectChoice(),"second private step did not resume draw");}
    static void prefixDepletion(){var m=fixture("{\"type\":\"draw\",\"amount\":1},"+SEARCH+",{\"type\":\"damage_counter\",\"target\":\"SELF\",\"amount\":1}");size(m,1);var card=zone(m,"deck").getFirst();int rng=m.randomTranscript().size();use(m);check(zone(m,"deck").isEmpty()&&zone(m,"hand").contains(card)&&m.activePokemonView(A).damage()==10&&!m.hasPendingEffectChoice()&&m.effectCardReveal()==null,"prefix-depleted private search interrupted suffix");check(m.randomTranscript().size()==rng,"empty private step shuffled");}
    static void concession(){var m=fixture(SEARCH);var before=List.copyOf(zone(m,"deck"));use(m);m.concede(B);check(zone(m,"deck").equals(before)&&m.effectCardReveal()==null&&!m.hasPendingEffectChoice(),"concession changed hidden deck or retained prompt");}
}
